local PhysicPotionMaker = {}
local PRODUCTS = {
    iron_potion = { name = "Železni napitek", ironCost = 1, woodCost = 2, leatherCost = 1, time = 5, cost = 155, prestige = 3, happiness = 2, description = "Železni napitek za krepitev." },
    bronze_potion = { name = "Bronast napitek", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 370, prestige = 5, happiness = 3, description = "Bronast napitek za apoteko." },
    silver_potion = { name = "Srebrni napitek", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 870, prestige = 10, happiness = 4, description = "Srebrni napitek za plemiške bolnike." },
    gilded_potion = { name = "Pozlačeni napitek", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1850, prestige = 20, happiness = 5, description = "Pozlačeni napitek za dvorno lekarno." },
    jewel_set_potion = { name = "Draguljasti napitek", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 3980, prestige = 36, happiness = 7, description = "Draguljasti napitek za kraljevo lekarno." },
    royal_sovereign_potion = { name = "Kraljevski suvereni napitek", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8500, prestige = 70, happiness = 13, description = "Suvereni napitek z biseri za krono." },
}
local BUILDINGS = {
    potion_workshop = { name = "Napitnična delavnica", cost = { gold = 345, wood = 180, stone = 140, iron = 7 }, upkeep = 7, qualityBonus = 5 },
    potion_house = { name = "Napitnična hiša", cost = { gold = 1230, wood = 360, stone = 275, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_potion_atelier = { name = "Mojstrski napitnični atelje", cost = { gold = 3080, wood = 420, stone = 525, silver = 36, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_physic_palace = { name = "Suverena napitnična palača", cost = { gold = 13100, wood = 635, stone = 835, gold = 84, jewel = 19 }, upkeep = 257, qualityBonus = 55, prestigeBonus = 50 },
}
PhysicPotionMaker.ironStock = 12; PhysicPotionMaker.bronzeStock = 10; PhysicPotionMaker.woodStock = 14; PhysicPotionMaker.leatherStock = 10; PhysicPotionMaker.silverStock = 8; PhysicPotionMaker.goldStock = 6; PhysicPotionMaker.jewelStock = 4; PhysicPotionMaker.pearlStock = 4
PhysicPotionMaker.productStock = {}; PhysicPotionMaker.buildings = {}; PhysicPotionMaker.maker = nil; PhysicPotionMaker.activeMaking = {}; PhysicPotionMaker.totalProducts = 0; PhysicPotionMaker.dayTimer = 0
function PhysicPotionMaker.init() PhysicPotionMaker.ironStock=12; PhysicPotionMaker.bronzeStock=10; PhysicPotionMaker.woodStock=14; PhysicPotionMaker.leatherStock=10; PhysicPotionMaker.silverStock=8; PhysicPotionMaker.goldStock=6; PhysicPotionMaker.jewelStock=4; PhysicPotionMaker.pearlStock=4; PhysicPotionMaker.productStock={}; PhysicPotionMaker.buildings={}; PhysicPotionMaker.maker=nil; PhysicPotionMaker.activeMaking={}; PhysicPotionMaker.totalProducts=0; PhysicPotionMaker.dayTimer=0; print("[PhysicPotionMaker] Royal Physic Potion Maker System initialized (6 products, 4 buildings)") end
function PhysicPotionMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PhysicPotionMaker.maker={name=n or ("Napitkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napitkar najet: %s (spretnost: %d)",PhysicPotionMaker.maker.name,s),"success") end; return true end
function PhysicPotionMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PhysicPotionMaker.build(id) local ok,e=PhysicPotionMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PhysicPotionMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PhysicPotionMaker.getQualityBonus() local b=0; for _,bd in ipairs(PhysicPotionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PhysicPotionMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PhysicPotionMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PhysicPotionMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PhysicPotionMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PhysicPotionMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PhysicPotionMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PhysicPotionMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PhysicPotionMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PhysicPotionMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PhysicPotionMaker.buildings==0 then return false,"Potrebna napitnična delavnica" end; if not PhysicPotionMaker.maker then return false,"Potreben napitkar" end; return true end
function PhysicPotionMaker.make(pt,qty) qty=qty or 1; local ok,e=PhysicPotionMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PhysicPotionMaker.ironStock=PhysicPotionMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PhysicPotionMaker.bronzeStock=PhysicPotionMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PhysicPotionMaker.woodStock=PhysicPotionMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PhysicPotionMaker.leatherStock=PhysicPotionMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PhysicPotionMaker.silverStock=PhysicPotionMaker.silverStock-d.silverCost*qty end; if d.goldCost then PhysicPotionMaker.goldStock=PhysicPotionMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PhysicPotionMaker.jewelStock=PhysicPotionMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PhysicPotionMaker.pearlStock=PhysicPotionMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PhysicPotionMaker.maker then t=math.max(1,t-math.floor(PhysicPotionMaker.maker.skill/13)) end; table.insert(PhysicPotionMaker.activeMaking,{id="potion_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PhysicPotionMaker.completeMaking(m) local q=1.0+(PhysicPotionMaker.getQualityBonus()/100); if PhysicPotionMaker.maker then q=q+(PhysicPotionMaker.maker.skill/140) end; q=math.min(2.5,q); PhysicPotionMaker.productStock[m.productType]=(PhysicPotionMaker.productStock[m.productType] or 0)+m.quantity; PhysicPotionMaker.totalProducts=PhysicPotionMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PhysicPotionMaker.maker then PhysicPotionMaker.maker.itemsMade=PhysicPotionMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PhysicPotionMaker.maker.skill=math.min(100,PhysicPotionMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napitek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"potion.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PhysicPotionMaker.update(dt) if not _G.state then return end; PhysicPotionMaker.dayTimer=PhysicPotionMaker.dayTimer+dt; if PhysicPotionMaker.dayTimer>=30 then PhysicPotionMaker.dayTimer=0; for i=#PhysicPotionMaker.activeMaking,1,-1 do local m=PhysicPotionMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PhysicPotionMaker.completeMaking(m); table.remove(PhysicPotionMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PhysicPotionMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PhysicPotionMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PhysicPotionMaker.getStats() return {ironStock=PhysicPotionMaker.ironStock,bronzeStock=PhysicPotionMaker.bronzeStock,woodStock=PhysicPotionMaker.woodStock,leatherStock=PhysicPotionMaker.leatherStock,silverStock=PhysicPotionMaker.silverStock,goldStock=PhysicPotionMaker.goldStock,jewelStock=PhysicPotionMaker.jewelStock,pearlStock=PhysicPotionMaker.pearlStock,productStock=PhysicPotionMaker.productStock,numBuildings=#PhysicPotionMaker.buildings,hasMaker=PhysicPotionMaker.maker~=nil,makerName=PhysicPotionMaker.maker and PhysicPotionMaker.maker.name or "—",makerSkill=PhysicPotionMaker.maker and PhysicPotionMaker.maker.skill or 0,activeMaking=#PhysicPotionMaker.activeMaking,totalProducts=PhysicPotionMaker.totalProducts} end
return PhysicPotionMaker
